-- Extends User Behaviour Loop Deeper Funnel API.sql -- Summarized: Back to SL -> Confirm on SAME route, split by same seat vs different seat -- st_no from create_order_details (joined only for cohort sessions — avoids full-table scan) -- Segment: 2026-05-14, Android, IND, MOBILE_APP WITH cache_sl AS ( SELECT mri_session_id, CAST(__time AS TIMESTAMP) AS cache_time, CAST(route_id AS VARCHAR) AS route_id_val, is_cached FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-05-14 00:00:00' AND __time < TIMESTAMP '2026-05-15 00:00:00' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' AND is_cached = TRUE ), base AS ( SELECT a.mri_session_id, CAST(a.__time AS TIMESTAMP) AS ts_time_utc, a.event_type, (CAST(a.src_id AS VARCHAR) || '-' || CAST(a.dest_id AS VARCHAR)) AS sd_id, CAST(a.doj AS VARCHAR) AS doj_val, CAST(a.route_id AS VARCHAR) AS route_id_val, CASE WHEN c.mri_session_id IS NOT NULL THEN 1 ELSE 0 END AS is_cached_event FROM user_interaction.api_events a LEFT JOIN cache_sl c ON a.mri_session_id = c.mri_session_id AND a.__time BETWEEN (c.cache_time - INTERVAL '3' SECOND) AND (c.cache_time + INTERVAL '3' SECOND) AND CAST(a.route_id AS VARCHAR) = c.route_id_val WHERE a.__time >= TIMESTAMP '2026-05-14 00:00:00' AND a.__time < TIMESTAMP '2026-05-15 00:00:00' AND a.event_src = 'CAPI' AND a.country = 'IND' AND a.channel = 'MOBILE_APP' AND a.os = 'Android' AND a.event_type IN ( 'Search-Routes', 'SeatLayout-ViewSeats', 'Tentative-MpaxAttribute', 'Tentative-CreateOrder', 'Tentative-OrderInfo', 'Payment-offlinePayments', 'Payment-Conclude' ) ), parameter_check AS ( SELECT *, FIRST_VALUE(sd_id) OVER ( PARTITION BY mri_session_id, event_type ORDER BY ts_time_utc ) AS first_sd, FIRST_VALUE(doj_val) OVER ( PARTITION BY mri_session_id, event_type ORDER BY ts_time_utc ) AS first_doj, FIRST_VALUE(route_id_val) OVER ( PARTITION BY mri_session_id, event_type ORDER BY ts_time_utc ) AS first_route, ROW_NUMBER() OVER ( PARTITION BY mri_session_id, event_type ORDER BY ts_time_utc ) AS occurrence_rank FROM base ), labeled AS ( SELECT mri_session_id, ts_time_utc, CASE WHEN event_type = 'Search-Routes' THEN CASE WHEN occurrence_rank = 1 THEN 'First SRP' WHEN sd_id = first_sd AND doj_val = first_doj THEN 'Same SD-DOJ SRP' ELSE 'Different SRP' END WHEN event_type = 'SeatLayout-ViewSeats' THEN CASE WHEN is_cached_event = 1 THEN 'Cached SL' WHEN occurrence_rank = 1 THEN 'First SL' WHEN route_id_val = first_route THEN 'Same route SL' ELSE 'Different route SL' END WHEN event_type = 'Tentative-MpaxAttribute' THEN 'CI' WHEN event_type = 'Tentative-CreateOrder' THEN 'TCO' WHEN event_type = 'Tentative-OrderInfo' THEN 'Pay' WHEN event_type = 'Payment-offlinePayments' THEN 'AddPay' WHEN event_type = 'Payment-Conclude' THEN 'Buddy' END AS step_label FROM parameter_check ), -- Session timing (same rules as deeper funnel) session_bounds AS ( SELECT mri_session_id, MIN(CASE WHEN step_label = 'Pay' THEN ts_time_utc END) AS first_pay_time, MAX(CASE WHEN step_label = 'Buddy' THEN ts_time_utc END) AS buddy_time FROM labeled GROUP BY mri_session_id ), -- First Same-route SL after Pay (back on same route_id as first SL) back_same_route AS ( SELECT l.mri_session_id, MIN(l.ts_time_utc) AS first_back_same_route_sl_time FROM labeled l INNER JOIN session_bounds sb ON l.mri_session_id = sb.mri_session_id WHERE l.step_label = 'Same route SL' AND l.ts_time_utc > sb.first_pay_time GROUP BY l.mri_session_id ), -- SRP-start sessions (comment out JOIN ss below to include all sessions) srp_start_sessions AS ( SELECT mri_session_id FROM ( SELECT mri_session_id, step_label, ROW_NUMBER() OVER (PARTITION BY mri_session_id ORDER BY ts_time_utc) AS rn FROM labeled ) x WHERE rn = 1 AND step_label = 'First SRP' ), -- Cohort: Pay -> back Same route SL -> Confirm (Buddy) back_same_route_confirm AS ( SELECT b.mri_session_id, sb.first_pay_time, b.first_back_same_route_sl_time, sb.buddy_time FROM back_same_route b INNER JOIN session_bounds sb ON b.mri_session_id = sb.mri_session_id INNER JOIN srp_start_sessions ss ON b.mri_session_id = ss.mri_session_id WHERE sb.first_pay_time IS NOT NULL AND sb.buddy_time IS NOT NULL AND sb.buddy_time > b.first_back_same_route_sl_time ), -- Seats: only for cohort sessions (scan-safe) order_seats AS ( SELECT o.mri_session_id, CAST(o.__time AS TIMESTAMP) AS order_time, TRIM(CAST(o.st_no AS VARCHAR)) AS st_no FROM user_interaction.create_order_details o INNER JOIN back_same_route_confirm c ON o.mri_session_id = c.mri_session_id WHERE o.__time >= TIMESTAMP '2026-05-14 00:00:00' AND o.__time < TIMESTAMP '2026-05-15 00:00:00' AND o.channel = 'MOBILE_APP' AND o.os = 'Android' AND o.country = 'IND' AND o.st_no IS NOT NULL ), -- Seat before first Pay (initial selection) initial_seat AS ( SELECT mri_session_id, st_no AS initial_st_no FROM ( SELECT c.mri_session_id, o.st_no, ROW_NUMBER() OVER ( PARTITION BY c.mri_session_id ORDER BY o.order_time ASC ) AS rn FROM back_same_route_confirm c INNER JOIN order_seats o ON c.mri_session_id = o.mri_session_id WHERE o.order_time < c.first_pay_time ) x WHERE rn = 1 ), -- Seat after back-to-same-route-SL, before Buddy (final selection) final_seat AS ( SELECT mri_session_id, st_no AS final_st_no FROM ( SELECT c.mri_session_id, o.st_no, ROW_NUMBER() OVER ( PARTITION BY c.mri_session_id ORDER BY o.order_time DESC ) AS rn FROM back_same_route_confirm c INNER JOIN order_seats o ON c.mri_session_id = o.mri_session_id WHERE o.order_time > c.first_back_same_route_sl_time AND o.order_time < c.buddy_time ) x WHERE rn = 1 ), session_seat_outcome AS ( SELECT c.mri_session_id, i.initial_st_no, f.final_st_no, CASE WHEN i.initial_st_no IS NULL OR f.final_st_no IS NULL THEN 'Back to SL then Confirm - same route, unknown seat' WHEN i.initial_st_no = f.final_st_no THEN 'Back to SL then Confirm - same route, same seat' ELSE 'Back to SL then Confirm - same route, different seat' END AS outcome_label FROM back_same_route_confirm c LEFT JOIN initial_seat i ON c.mri_session_id = i.mri_session_id LEFT JOIN final_seat f ON c.mri_session_id = f.mri_session_id ) -- Summarized output (required rows only) SELECT outcome_label, COUNT(*) AS distinct_sessions, ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 2) AS pct_of_cohort FROM session_seat_outcome WHERE outcome_label IN ( 'Back to SL then Confirm - same route, same seat', 'Back to SL then Confirm - same route, different seat' ) GROUP BY 1 ORDER BY distinct_sessions DESC -- ============================================================================= -- TOGGLE: include unknown seat + cohort size (uncomment to run instead) -- ============================================================================= -- SELECT outcome_label, COUNT(*) AS distinct_sessions -- FROM session_seat_outcome -- GROUP BY 1 ORDER BY 2 DESC; -- -- SELECT COUNT(*) AS total_back_same_route_confirm FROM back_same_route_confirm;
